import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import './App.css';

// Components
import Navbar from './components/Navbar';
import ProtectedRoute from './components/ProtectedRoute';
import MoodTracker from './components/MoodTracker';

// Pages
import Home from './pages/Home';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Clinics from './pages/Clinics';
import ClinicDetail from './pages/ClinicDetail';
import Articles from './pages/Articles';
import ArticleDetail from './pages/ArticleDetail';
import Journals from './pages/Journals';
import MyProfile from './pages/MyProfile';
import UserProfile from './pages/UserProfile';

// Services
import { getCurrentUser } from './services/auth';

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    checkAuth();
  }, []);

  const checkAuth = async () => {
    try {
      const token = localStorage.getItem('token');
      if (token) {
        const userData = await getCurrentUser();
        setUser(userData);
      }
    } catch (error) {
      console.error('Auth check failed:', error);
      localStorage.removeItem('token');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (userData, token) => {
    localStorage.setItem('token', token);
    setUser(userData);
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setUser(null);
  };

  if (loading) {
    return <div className="loading">Loading...</div>;
  }

  return (
    <Router>
      <div className="app">
        <Navbar user={user} onLogout={handleLogout} />
        <Routes>
          <Route path="/" element={<Home user={user} />} />
          <Route path="/login" element={user ? <Navigate to="/" /> : <Login onLogin={handleLogin} />} />
          <Route path="/signup" element={user ? <Navigate to="/" /> : <Signup onLogin={handleLogin} />} />
          <Route path="/clinics" element={<Clinics />} />
          <Route path="/clinics/:id" element={<ClinicDetail user={user} />} />
          <Route path="/articles" element={<Articles user={user} />} />
          <Route path="/articles/:id" element={<ArticleDetail user={user} />} />
          <Route path="/journals" element={<Journals user={user} />} />
          <Route path="/profile" element={
            <ProtectedRoute user={user}>
              <MyProfile user={user} />
            </ProtectedRoute>
          } />
          <Route path="/users/:id" element={<UserProfile />} />
        </Routes>
        {user && <MoodTracker />}
      </div>
    </Router>
  );
}

export default App;
